import{_ as a,o,c as t,ae as i}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Expense Tracker: Koala Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"v1/en/legal/privacy.md","filePath":"v1/en/legal/privacy.md"}'),r={name:"v1/en/legal/privacy.md"};function n(s,e,l,c,p,d){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="expense-tracker-koala-privacy-policy" tabindex="-1"><strong>Expense Tracker: Koala</strong> Privacy Policy <a class="header-anchor" href="#expense-tracker-koala-privacy-policy" aria-label="Permalink to &quot;**Expense Tracker: Koala** Privacy Policy&quot;">​</a></h1><p>Last Updated: April 24, 2026</p><p>Effective Date: April 24, 2026</p><p>Expense Tracker: Koala (the “App”, or “Koala”) takes your personal information seriously. This Expense Tracker: Koala Privacy Policy (the “Policy”) explains how we collect, use, store, share, and protect your personal information, as well as how you can exercise your rights.</p><p>Please read and understand this Policy carefully before using the App. By tapping “Agree/Accept” or continuing to use the App, you acknowledge that you have fully understood and agree to this Policy.</p><h2 id="_1-who-we-are" tabindex="-1"><strong>1. Who We Are</strong> <a class="header-anchor" href="#_1-who-we-are" aria-label="Permalink to &quot;**1. Who We Are**&quot;">​</a></h2><p>● Operator: Expense Tracker: Koala</p><p>● Contact Email: <a href="mailto:ruanweidev@163.com" target="_blank" rel="noreferrer">ruanweidev@163.com</a></p><h2 id="_2-how-we-collect-and-use-personal-information" tabindex="-1"><strong>2. How We Collect and Use Personal Information</strong> <a class="header-anchor" href="#_2-how-we-collect-and-use-personal-information" aria-label="Permalink to &quot;**2. How We Collect and Use Personal Information**&quot;">​</a></h2><p>We follow the principles of legality, legitimacy, and necessity when collecting and using information for purposes such as providing features, ensuring operational security, and improving user experience. The types of information we collect may vary depending on whether you sign in and which features you use.</p><h3 id="_2-1-information-you-provide" tabindex="-1"><strong>2.1 Information You Provide</strong> <a class="header-anchor" href="#_2-1-information-you-provide" aria-label="Permalink to &quot;**2.1 Information You Provide**&quot;">​</a></h3><ol><li>Account and identity information (if applicable)</li></ol><p>● When you sign in using a third-party account (e.g., Sign in with Apple), we may obtain necessary identifier information returned by that third party to complete sign-in and account management.</p><ol start="2"><li>Data you enter or import while using the App</li></ol><p>● For example, bills, categories, tags, notes, and imported file content that you record in the App. Such data is generally stored locally on your device, or stored on our servers if you enable any synchronization capability (if available).</p><h3 id="_2-2-information-we-collect-automatically" tabindex="-1"><strong>2.2 Information We Collect Automatically</strong> <a class="header-anchor" href="#_2-2-information-we-collect-automatically" aria-label="Permalink to &quot;**2.2 Information We Collect Automatically**&quot;">​</a></h3><p>To keep the App running properly, perform analytics, and improve stability and security, we may automatically collect the following information (relevant SDKs will only be formally initialized and start reporting after we obtain your consent):</p><p>● Device information: device model, device name, operating system version, app version, language settings, etc.</p><p>● Device identifiers: may include Android ID, IMEI (if available from the system), IDFA (if authorized by you), OPENUDID, GUID, IP address, MAC address (subject to system limitations), etc., for analytics, anti-fraud, troubleshooting, and security purposes.</p><p>● Network information: network type, carrier information (if available from the system), network request failure information, etc., for connection quality optimization and stability analysis.</p><p>● Log information: launch events, crash/exception stacks, performance data, page navigation paths, etc., for issue diagnosis and performance improvement.</p><h3 id="_2-3-permissions-and-feature-mapping-overview" tabindex="-1"><strong>2.3 Permissions and Feature Mapping (Overview)</strong> <a class="header-anchor" href="#_2-3-permissions-and-feature-mapping-overview" aria-label="Permalink to &quot;**2.3 Permissions and Feature Mapping (Overview)**&quot;">​</a></h3><p>To provide certain features, the App may request or use device permissions. Permission names and prompts may differ by system version; please refer to the actual system prompts:</p><p>● Network access: used for online requests, synchronization, analytics, etc.</p><p>● Photos/files access (e.g., import/export, file selection, sharing, saving images): used to let you select or save files.</p><p>● Purchase/subscription capability (e.g., in-app purchases): used to complete payments and check subscription status, etc.</p><p>We will not proactively request permissions beyond what is necessary for the features you choose to use.</p><h2 id="_3-third-party-sdks-and-information-sharing" tabindex="-1"><strong>3. Third-Party SDKs and Information Sharing</strong> <a class="header-anchor" href="#_3-third-party-sdks-and-information-sharing" aria-label="Permalink to &quot;**3. Third-Party SDKs and Information Sharing**&quot;">​</a></h2><p>To provide analytics and app performance monitoring, the App integrates third-party SDKs. Such SDKs may collect relevant information. We will only call the formal initialization APIs of such SDKs after obtaining your consent, enabling them to start collecting and reporting data. If you do not consent, we will not formally initialize them.</p><h3 id="_3-1-umeng-sdk-analytics-app-performance-monitoring" tabindex="-1"><strong>3.1 Umeng+ SDK (Analytics / App Performance Monitoring)</strong> <a class="header-anchor" href="#_3-1-umeng-sdk-analytics-app-performance-monitoring" aria-label="Permalink to &quot;**3.1 Umeng+ SDK (Analytics / App Performance Monitoring)**&quot;">​</a></h3><p>We integrate the Umeng+ SDK for analytics and app performance monitoring. The Umeng+ SDK may collect the following information to provide analytics services, calibrate report accuracy based on location, and provide basic anti-fraud capabilities:</p><p>● Device information and device identifiers: MAC address, unique device identifier (IMEI / Android ID / IDFA / OPENUDID / GUID, etc.)</p><p>● Network information: IP address</p><p>● SIM-related information: IMSI (if available from the system)</p><p>The Umeng+ SDK will be formally initialized after you agree to this Policy. If you do not agree, we will not call the Umeng+ SDK’s formal initialization APIs.</p><h2 id="_4-how-we-store-and-protect-your-information" tabindex="-1"><strong>4. How We Store and Protect Your Information</strong> <a class="header-anchor" href="#_4-how-we-store-and-protect-your-information" aria-label="Permalink to &quot;**4. How We Store and Protect Your Information**&quot;">​</a></h2><ol><li>Storage location and retention period</li></ol><p>● We retain your personal information only for as long as necessary to fulfill the purposes of this service, unless otherwise required by applicable laws and regulations.</p><p>● Your bookkeeping data may primarily be stored in a local database on your device. If you enable cloud synchronization (if available), relevant data may be uploaded to and stored on our servers.</p><ol start="2"><li>Security measures</li></ol><p>● We take reasonable and feasible technical and administrative measures to protect your information against leakage, damage, or loss.</p><p>● However, the internet environment is not absolutely secure. If a security incident occurs due to force majeure or reasons not attributable to us, we will handle it in accordance with applicable laws and regulations.</p><h2 id="_5-your-rights" tabindex="-1"><strong>5. Your Rights</strong> <a class="header-anchor" href="#_5-your-rights" aria-label="Permalink to &quot;**5. Your Rights**&quot;">​</a></h2><p>Subject to applicable laws and regulations and the App’s capabilities, you may exercise the following rights:</p><p>● Access and correction: you may view and edit the data you entered in the App.</p><p>● Deletion: you may delete relevant records in the App. If cloud data is involved (if available), we will provide deletion synchronization or account deletion options in line with product capabilities.</p><p>● Withdrawal of consent: you may withdraw authorization or disable relevant switches in system or app settings. Withdrawing consent does not affect the legality of processing activities conducted based on your consent before the withdrawal.</p><h2 id="_6-children-s-privacy" tabindex="-1"><strong>6. Children’s Privacy</strong> <a class="header-anchor" href="#_6-children-s-privacy" aria-label="Permalink to &quot;**6. Children’s Privacy**&quot;">​</a></h2><p>If you are under 14 years old, please read this Policy and use the App under the supervision and guidance of your legal guardian. We will protect minors’ personal information in accordance with applicable laws and regulations.</p><h2 id="_7-updates-to-this-policy" tabindex="-1"><strong>7. Updates to This Policy</strong> <a class="header-anchor" href="#_7-updates-to-this-policy" aria-label="Permalink to &quot;**7. Updates to This Policy**&quot;">​</a></h2><p>We may revise this Policy from time to time. If a revision materially affects your rights under this Policy, we will notify you through in-app prompts, pop-ups, or announcements. By continuing to use the App, you agree to the updated Policy.</p><h2 id="_8-contact-us" tabindex="-1"><strong>8. Contact Us</strong> <a class="header-anchor" href="#_8-contact-us" aria-label="Permalink to &quot;**8. Contact Us**&quot;">​</a></h2><p>If you have any questions, comments, or suggestions about this Policy, please contact us:</p><p>● Operator: Expense Tracker: Koala</p><p>● Contact Email: <a href="mailto:ruanweidev@163.com" target="_blank" rel="noreferrer">ruanweidev@163.com</a></p><h1 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h1>',56)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
